  try {
    // 1. Geometry Definitions
    // Define the region of interest: Sumatra and Indonesian Borneo
    // Using FAO/GAUL/2015/level1 for administrative boundaries
    const gaul = ee.FeatureCollection("FAO/GAUL/2015/level1");

    // Filter for Indonesia's provinces that make up Sumatra and Borneo (Kalimantan)
    const sumatraProvinces = [
      'Aceh', 'Sumatera Utara', 'Sumatera Barat', 'Riau', 'Jambi', 'Sumatera Selatan',
      'Bengkulu', 'Lampung', 'Kepulauan Bangka Belitung', 'Kepulauan Riau'
    ];
