      'Kalimantan Barat', 'Kalimantan Tengah', 'Kalimantan Selatan',
      'Kalimantan Timur', 'Kalimantan Utara'
    ];

    const sumatra = gaul.filter(ee.Filter.inList('ADM1_NAME', sumatraProvinces));
    const kalimantan = gaul.filter(ee.Filter.inList('ADM1_NAME', kalimantanProvinces));

    const roi = sumatra.merge(kalimantan).geometry();

    if (roi.area().getInfo() === 0) {
      console.log("C3: Region of interest is empty or invalid.");
      return;
    }

    // 2. Time Definitions
    const start2022 = '2022-01-01';
    const end2022 = '2022-12-31';
    const start2023 = '2023-01-01';
    const end2023 = '2023-12-31';

    // 3. Data Acquisition
    // Using MODIS MCD14DL (Thermal Anomalies/Fire Daily L3)
    const fireCollection = ee.FeatureCollection('MODIS/051/MCD14DL');

    // Filter for 2022
    const fires2022 = fireCollection
      .filterBounds(roi)
      .filterDate(start2022, end2022);

    // Filter for 2023
    const fires2023 = fireCollection
      .filterBounds(roi)
      .filterDate(start2023, end2023);

    // Get fire counts
    const count2022 = await fires2022.size().getInfo();
    const count2023 = await fires2023.size().getInfo();

    // 4. Validation & Final Answer
    if (count2022 === 0 && count2023 === 0) {
      console.log("No active fire detections found for either 2022 or 2023.");
      console.log("C1");
      return;
    }

    console.log(`2022 Fire Detections (Sumatra & Borneo): ${count2022}`);
    console.log(`2023 Fire Detections (Sumatra & Borneo): ${count2023}`);

    if (count2023 > count2022) {
      console.log("A"); // Yes, active fire detections increased
    } else {
      console.log("B"); // No, active fire detections did not increase
    }

  } catch (error) {
    console.error("Analysis failed:", error);
    console.log("D"); // General error or memory issue
  }
}

